algorithms.pseudocode:
def leaf(x):  return sha256(b'\x00' + x)
def node(l, r): return sha256(b'\x01' + l + r)

def root(leaves):
    if len(leaves) == 1: return leaf(leaves[0])
    k = largest_power_of_two_less_than(len(leaves))
    return node(root(leaves[:k]), root(leaves[k:]))

def verify_inclusion(leaf_bytes, index, size, path, root_hash):
    h = leaf(leaf_bytes)
    for sib, sib_is_left in path_directions(index, size, path):
        h = node(sib, h) if sib_is_left else node(h, sib)
    return h == root_hash

def reconcile(service, window):
    produced = outbox_metrics.count(service, window)   # emitted inside txns
    ids_ledger = ledger.event_ids(service, window)
    if produced != len(ids_ledger):
        missing = outbox_archive.ids(service, window) - ids_ledger
        alert('AUDIT_GAP', service, window, missing[:100])
    for p in partitions:
        assert ledger.max_seq(p) - ledger.min_seq(p) + 1 == ledger.count(p)
